public int hIndex(int[] citations) {
    int n = citations.length;
    int[] buckets = new int[n + 1];
    for (int c : citations) {
        buckets[Math.min(c, n)]++;
    }
    int total = 0;
    for (int j = n; j >= 0; j--) {
        total += buckets[j];
        if (total >= j) {
            return j;
        }
    }
    return 0;
}

