def hIndex(self, citations: list[int]) -> int:
    n = len(citations)
    buckets = [0] * (n + 1)
    for c in citations:
        buckets[min(c, n)] += 1
    total = 0
    for j in range(n, -1, -1):
        total += buckets[j]
        if total >= j:
            return j
    return 0

